exempt = (input('exempt_assets') || {})['CKV_AWS_35'] || []

control 'CKV_AWS_35' do
  title 'Ensure CloudTrail logs are encrypted at rest using KMS CMKs'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_cloudtrail resources that actually exist, read through the stock
    inspec-aws aws_cloudtrail_trail resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Without SSE-KMS the log objects are readable by anyone who can read the
    bucket. With a CMK, reading them additionally requires a decrypt grant
    on the key, so bucket access alone does not disclose the audit record.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_cloudtrail: kms_key_id is CKV_ANY
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_cloudtrail:

      resource "aws_kms_key" "trail" {
        description         = "CloudTrail log encryption"
        enable_key_rotation = true
      }

      resource "aws_cloudtrail" "org" {
        name                          = "org-trail"
        s3_bucket_name                = aws_s3_bucket.trail.id
        kms_key_id                    = aws_kms_key.trail.arn
        is_multi_region_trail         = true
        enable_log_file_validation    = true
        include_global_service_events = true
      }

    Out of band — aws_cloudtrail:

      aws cloudtrail update-trail --name org-trail --kms-key-id <key-arn>

    Note (aws_cloudtrail): The key policy must let cloudtrail.amazonaws.com call
    GenerateDataKey* for this trail's ARN, or delivery stops silently. Log files
    already delivered stay under whatever protection they were written with.
  FIX

  tag checkov_id:            'CKV_AWS_35'
  tag checkov_category:      'LOGGING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_cloudtrail]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/cloudtrail#kms-key-id'
  tag nist:                  ['AU-9', 'SC-28', 'SC-28 (1)']
  tag nist_r4:               ['AU-9', 'SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-000162', 'CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  ids = aws_cloudtrail_trails.names
  in_scope = ids.reject { |id| checkov_exempt?(id: id, type: 'aws_cloudtrail', rules: exempt) }

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_cloudtrail in scope') { applicable }

  in_scope.each do |id|
    describe aws_cloudtrail_trail(trail_name: id) do
      its('encrypted?') { should eq true }
    end
  end
end
